script:
const selected = await $zodula
  .doctype('Delivery Note')
  .select()
  .limit(ctx.limit || 50)
  .sort('price_project', 'asc');

const sourceRows = selected.docs || [];
const groupedRows = [];
let currentPriceProject = null;

for (const row of sourceRows) {
  const priceProject = row.price_project || 'No Price Project';
  if (priceProject !== currentPriceProject) {
    groupedRows.push({
      id: `group-${priceProject}`,
      price_project: `Price Project: ${priceProject}`,
      customer_name: '',
      posting_date: null,
      grand_total: null,
    });
    currentPriceProject = priceProject;
  }

  groupedRows.push(row);
}

return {
  rows: groupedRows,
  columns: [
    { key: 'price_project', label: 'Price Project', sortable: true },
    { key: 'id', label: 'Delivery Note', sortable: true },
    { key: 'customer_name', label: 'Customer', sortable: true },
    { key: 'posting_date', label: 'Posting Date', sortable: true },
    { key: 'grand_total', label: 'Grand Total', sortable: true },
  ],
  count: sourceRows.length,
};
